import{_ as l,o as r,c as t,a2 as o}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"狼族少年","description":"","frontmatter":{},"headers":[],"relativePath":"中层/人物/狼族少年.md","filePath":"中层/人物/狼族少年.md","lastUpdated":1787065118000}'),i={name:"中层/人物/狼族少年.md"};function n(e,a,s,h,g,u){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="狼族少年" tabindex="-1">狼族少年 <a class="header-anchor" href="#狼族少年" aria-label="Permalink to &quot;狼族少年&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>称号</strong>：毁灭神权（下位）二代载体，狼族救世主</li><li><strong>种族</strong>：狼族</li><li><strong>性别</strong>：雄性</li><li><strong>年龄</strong>：青少年至青年（具体年龄随故事进展）</li><li><strong>当前状态</strong>：失忆状态，被拉斯塔在山洞中发现后带回红星孤儿院</li><li><strong>神权状态</strong>：毁灭神权（下位）载体，已完全觉醒</li><li><strong>基因锁状态</strong>：基因锁已破除，不受狼族&quot;天真纯善&quot;特质影响</li><li><strong>重要性</strong>：故事核心主角，开启主角团向外拓展的探险之路，狼族崛起的领袖</li></ul><h2 id="外貌特征与形态" tabindex="-1">外貌特征与形态 <a class="header-anchor" href="#外貌特征与形态" aria-label="Permalink to &quot;外貌特征与形态&quot;">​</a></h2><ul><li><strong>毛色</strong>：灰黑色，受毁灭神权影响有少许红色花纹</li><li><strong>眼神</strong>：正常眼神，有时让人感觉诡异的空洞；神权显现时瞳孔变为红色圆环（与毁灭神环一致）并发光</li><li><strong>体型</strong>：符合狼族特征的青少年至青年体型</li><li><strong>服装</strong>：穿着红星孤儿院的简朴服装</li><li><strong>气质</strong>：沉默，与其他孤儿有距离感</li></ul><h2 id="背景简史" tabindex="-1">背景简史 <a class="header-anchor" href="#背景简史" aria-label="Permalink to &quot;背景简史&quot;">​</a></h2><h3 id="出生与收养" tabindex="-1">出生与收养 <a class="header-anchor" href="#出生与收养" aria-label="Permalink to &quot;出生与收养&quot;">​</a></h3><ul><li><strong>出生不明</strong>：出生不明，受基底层影响，具体出生时间、地点、父母均不可查</li><li><strong>结识小白狼</strong>：幼年被小白狼结识</li><li><strong>南方狼村收养</strong>：被南方狼村收养，度过约十年幸福生活</li></ul><h3 id="黑暗时代约-180-年-奴隶官事件" tabindex="-1">黑暗时代约 180 年：奴隶官事件 <a class="header-anchor" href="#黑暗时代约-180-年-奴隶官事件" aria-label="Permalink to &quot;黑暗时代约 180 年：奴隶官事件&quot;">​</a></h3><ul><li><strong>被捕</strong>：被猪族奴隶官抓走</li><li><strong>目睹惨死</strong>：亲眼目睹亲友与小白狼在面前屈辱惨死</li><li><strong>初次觉醒</strong>：极度的仇恨与愤怒点燃力量，神权（下位毁灭）初次觉醒</li></ul><h3 id="起义与建国" tabindex="-1">起义与建国 <a class="header-anchor" href="#起义与建国" aria-label="Permalink to &quot;起义与建国&quot;">​</a></h3><ul><li><strong>解放奴隶厂</strong>：屠戮奴隶厂，解放被囚禁的狼族</li><li><strong>领导起义</strong>：成为狼族反抗运动的领导者</li><li><strong>初步建国</strong>：带领解放的狼族建立初步的国家</li></ul><h3 id="背叛与神权完全觉醒" tabindex="-1">背叛与神权完全觉醒 <a class="header-anchor" href="#背叛与神权完全觉醒" aria-label="Permalink to &quot;背叛与神权完全觉醒&quot;">​</a></h3><ul><li><strong>联合背刺</strong>：遭新五族中猪、虎、豹、蝠四族联合背刺，狼族死伤惨重</li><li><strong>信任崩塌</strong>：彻底失去幻想，信任崩塌</li><li><strong>神权完全觉醒</strong>：仇恨激活本质，彻底登神</li></ul><h3 id="四方巡游与消失" tabindex="-1">四方巡游与消失 <a class="header-anchor" href="#四方巡游与消失" aria-label="Permalink to &quot;四方巡游与消失&quot;">​</a></h3><ul><li><strong>独自巡游</strong>：此后独自一人巡游大地四方</li><li><strong>灭绝四族</strong>：数年内灭绝猪、虎、豹、蝠四族，彻底改变大陆种族格局</li><li><strong>突然消失</strong>：在即将灭绝鹰族时突然消失</li></ul><h3 id="当前-失忆于红星孤儿院" tabindex="-1">当前：失忆于红星孤儿院 <a class="header-anchor" href="#当前-失忆于红星孤儿院" aria-label="Permalink to &quot;当前：失忆于红星孤儿院&quot;">​</a></h3><ul><li><strong>失忆状态</strong>：当前处于失忆状态，在红星孤儿院准备与拉斯塔一同冒险</li><li><strong>身份认知</strong>：对自己毁灭神的身份完全不清楚，自认力量为普通魔法</li></ul><h2 id="人格特质" tabindex="-1">人格特质 <a class="header-anchor" href="#人格特质" aria-label="Permalink to &quot;人格特质&quot;">​</a></h2><h3 id="基因锁压制时" tabindex="-1">基因锁压制时 <a class="header-anchor" href="#基因锁压制时" aria-label="Permalink to &quot;基因锁压制时&quot;">​</a></h3><ul><li><strong>天真纯善</strong>：表现为天真纯善、易信他人的性格，认为所有人都是同伴</li><li><strong>驯化倾向</strong>：易于相信他人言论，极易被洗脑驯化</li></ul><h3 id="基因锁破除后-真实特质" tabindex="-1">基因锁破除后（真实特质） <a class="header-anchor" href="#基因锁破除后-真实特质" aria-label="Permalink to &quot;基因锁破除后（真实特质）&quot;">​</a></h3><ul><li><strong>极端团结</strong>：展现狼族的真实特质——<strong>极端团结</strong>，成员之间无需博弈与欺骗</li><li><strong>生理交流</strong>：狼族能够通过眼神交流确认对方是否真诚——若心存欺骗则无法完成相应表达</li></ul><h3 id="经历塑造的性格" tabindex="-1">经历塑造的性格 <a class="header-anchor" href="#经历塑造的性格" aria-label="Permalink to &quot;经历塑造的性格&quot;">​</a></h3><ul><li><strong>仇恨与愤怒</strong>：经历亲友惨死与种族背叛后，内心积累深重仇恨与愤怒</li><li><strong>主动接受</strong>：对灭绝种族的决心持主动接受态度</li></ul><h2 id="能力状态" tabindex="-1">能力状态 <a class="header-anchor" href="#能力状态" aria-label="Permalink to &quot;能力状态&quot;">​</a></h2><ul><li><strong>战力梯队</strong>：世界顶尖战斗力梯队成员（与创造神、维斯塔、拉斯塔并列）</li><li><strong>完全觉醒</strong>：神权已完全觉醒，但因失忆状态使用受限</li><li><strong>力量感知</strong>：因神权被克隆体稀释，力量薄弱到无法感知自身神权，自认力量为普通魔法</li></ul><blockquote><p><strong>中层真相</strong>：以下内容为表层生灵无法知晓的真相。</p></blockquote><h2 id="深层设定-中层真相" tabindex="-1">深层设定（中层真相） <a class="header-anchor" href="#深层设定-中层真相" aria-label="Permalink to &quot;深层设定（中层真相）&quot;">​</a></h2><h3 id="基因锁的真相" tabindex="-1">基因锁的真相 <a class="header-anchor" href="#基因锁的真相" aria-label="Permalink to &quot;基因锁的真相&quot;">​</a></h3><ul><li><strong>&quot;天真纯善&quot;是基因锁</strong>：狼族的&quot;天真纯善&quot;并非真实特质，而是神机故意设置的<strong>基因锁</strong>，用于压制狼族的凶残本性</li><li><strong>锁的删除</strong>：主角在无意间，通过神权删除了狼族族群的&quot;概念锁&quot;——但并非概念性抹除，而是类似截肢手术，仅删除他所能看到的当下的狼族；未触及基因锁的遗传根源，因此新一代狼族出生后基因锁会重新显现</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../../表层/种族/狼族" class="layer-link" data-layer="表层">狼族</a></p></blockquote><h3 id="克隆体稀释毁灭神权" tabindex="-1">克隆体稀释毁灭神权 <a class="header-anchor" href="#克隆体稀释毁灭神权" aria-label="Permalink to &quot;克隆体稀释毁灭神权&quot;">​</a></h3><ul><li><strong>技术干预</strong>：神机在太空建造克隆仓库，克隆无数个与毁灭神本体完全一致的克隆体</li><li><strong>意识连接</strong>：通过意识连接技术让克隆体成为毁灭神&quot;意识整体&quot;的一部分</li><li><strong>稀释原理</strong>：毁灭神的神权锚定其&quot;意识整体&quot;（本体 + 所有克隆体），神权总量恒定，被无数克隆体稀释后力量薄弱到无法感知自身神权</li><li><strong>生理层面失忆</strong>：对毁灭神实施生理层面的大脑记忆修改，使其失忆，成为一位普通少年</li></ul><h3 id="神权回流伏笔" tabindex="-1">神权回流伏笔 <a class="header-anchor" href="#神权回流伏笔" aria-label="Permalink to &quot;神权回流伏笔&quot;">​</a></h3><ul><li>克隆仓库若被损毁、克隆体批量死亡，被稀释的神权则会回流至本体</li><li>可能引发主角失控/恢复神权</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../世界/神机谋划">神机谋划</a></p></blockquote><h2 id="关键关系" tabindex="-1">关键关系 <a class="header-anchor" href="#关键关系" aria-label="Permalink to &quot;关键关系&quot;">​</a></h2><h3 id="与维斯塔-红星孤儿院院长" tabindex="-1">与维斯塔（红星孤儿院院长） <a class="header-anchor" href="#与维斯塔-红星孤儿院院长" aria-label="Permalink to &quot;与维斯塔（红星孤儿院院长）&quot;">​</a></h3><ul><li><strong>监护关系</strong>：当前维斯塔是其监护人</li><li><strong>教导与控制</strong>：维斯塔教导其如何控制力量，并回答其提出的问题</li><li><strong>真相来源</strong>：维斯塔的回答有些时候可能与其余地方听到的答案不一致，或回答一些其余地方根本没有答案的问题——维斯塔的回答总是真正的真相</li></ul><h3 id="与拉斯塔-四代变化神" tabindex="-1">与拉斯塔（四代变化神） <a class="header-anchor" href="#与拉斯塔-四代变化神" aria-label="Permalink to &quot;与拉斯塔（四代变化神）&quot;">​</a></h3><ul><li><strong>孤儿院同伴</strong>：同为红星孤儿院的孤儿</li><li><strong>日常互动</strong>：有日常的互动和交流</li><li><strong>神权关联</strong>：毁灭神与变化神的潜在关联，是神机计划的一部分</li><li><strong>同伴感情</strong>：建立了同伴感情，是冒险路途上的伙伴</li></ul><h3 id="与狼族" tabindex="-1">与狼族 <a class="header-anchor" href="#与狼族" aria-label="Permalink to &quot;与狼族&quot;">​</a></h3><ul><li><strong>救世主身份</strong>：狼族的救世主、反抗象征、建国希望</li><li><strong>历史影响</strong>：其行动使狼族从奴隶种族走向独立</li></ul><h3 id="与神机" tabindex="-1">与神机 <a class="header-anchor" href="#与神机" aria-label="Permalink to &quot;与神机&quot;">​</a></h3><ul><li><strong>关键棋子</strong>：神机整体谋划中最关键的棋子——神机需要可控的毁灭神应对危机</li><li><strong>可控载体</strong>：被神机作为可控的毁灭神权载体进行培养和观察</li></ul><h3 id="与小白狼-上位毁灭神" tabindex="-1">与小白狼（上位毁灭神） <a class="header-anchor" href="#与小白狼-上位毁灭神" aria-label="Permalink to &quot;与小白狼（上位毁灭神）&quot;">​</a></h3><ul><li><strong>青梅竹马</strong>：与上位毁灭神（小白狼）同为孤儿、被同一村长收养，从小相识</li><li><strong>死亡影响</strong>：小白狼被铁矛刺死，其死亡是引爆主角仇恨、促使主角登神的导火索之一</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><p><a href="./../../表层/人物/狼族少年" class="layer-link" data-layer="表层">狼族少年（表层档案）</a></p></li><li><p><a href="./../../叙事与伏笔/伏笔洋葱层分类">伏笔洋葱层分类</a></p></li><li><p><a href="./../../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a></p></li><li><p><a href="./../../表层/种族/狼族" class="layer-link" data-layer="表层">狼族</a></p></li><li><p><a href="./../../底层/人物/上位毁灭神" class="layer-link" data-layer="底层">上位毁灭神</a></p></li><li><p><a href="./../世界/神机谋划">神机谋划</a></p></li><li><p><a href="./../../表层/历史/黑暗时代" class="layer-link" data-layer="表层">黑暗时代</a></p></li><li><p><a href="./维斯塔">维斯塔</a></p></li><li><p><a href="./拉斯塔">拉斯塔</a></p></li></ul><hr>',52)])])}const q=l(i,[["render",n]]);export{c as __pageData,q as default};
